/**
 * Regel R5: bei mehr als vier Potenzialen wird je Epic einzeln geprüft.
 *
 * Grund: der Compliance-Agent bekommt sonst alle Epics in einem Aufruf
 * (JSON.stringify($json.epics)). Bei vielen Epics trifft das Modell die
 * Mengengrenze und lässt welche weg, ohne es zu melden - genau der Fehler,
 * den BC3 am 20.08. in BC4s Generator gefunden hat (Befund K8).
 */
const rein = $input.first().json;
const a = rein.umschlag?.aggregat;
if (!a) throw new Error('Der Umschlag enthält kein Aggregat. Lief BC3-20 durch?');

const einzeln = rein.umschlag?.plan?.in_teilmengen === true;
const epics = a.epics || [];

if (!einzeln || epics.length <= 1) {
  return [{ json: a }];
}

// Ein Item je Epic, sonst derselbe Kontext
return epics.map((e, i) => ({
  json: { ...a, epics: [e], _teil: i + 1, _teile: epics.length },
}));

